  22: 
  23:   private async copyToClipboard(data: string): Promise<void> {
  24:     try {
  25:       const systemPasteboard = pasteboard.getSystemPasteboard();
  26:       systemPasteboard.clearData();
  27:       const pasteData = pasteboard.createData(pasteboard.MIMETYPE_TEXT_PLAIN, data);
  28:       systemPasteboard.setPasteData(pasteData);
  29:       promptAction.showToast({ message: '已复制到剪贴板', duration: 1500 });
  30:     } catch (e) {
  31:       promptAction.showToast({ message: '复制失败', duration: 1500 });
  32:     }
  33:   }
