  35:   build() {
  36:     if (this.visible) {
  37:       Stack() {
  38:         // Backdrop
  39:         Column()
  40:           .width('100%')
  41:           .height('100%')
  42:           .backgroundColor(this.colors.BLACK)
  43:           .opacity(0.5)
  44:           .onClick(() => {
  45:             this.visible = false;
  46:           })
  47: 
  48:         // Dialog Content
  49:         Column() {
  50:           Column() {
  51:             Text(this.title.length > 0 ? this.title : '数据同步')
  52:               .fontSize(20)
  53:               .fontWeight(FontWeight.Bold)
  54:               .fontColor(this.colors.TEXT_PRIMARY)
  55:               .margin({ bottom: 12 })
  56: 
  57:             if (this.message.length > 0) {
  58:               Text(this.message)
  59:                 .fontSize(13)
  60:                 .fontColor(this.colors.TEXT_SECONDARY)
  61:                 .margin({ bottom: 12 })
  62:             }
  63: 
  64:             // Data area
  65:             TextArea({ text: this.data, placeholder: this.isImport ? '在此粘贴 JSON...' : '' })
  66:               .width('100%')
  67:               .height(180)
  68:               .fontSize(12)
  69:               .backgroundColor(this.colors.BACKGROUND_SECONDARY)
  70:               .borderRadius(8)
  71:               .padding(8)
  72:               .enabled(this.isImport)
  73:               .onChange((value: string) => {
  74:                 this.data = value;
  75:               })
  76:               .margin({ bottom: 16 })
  77: 
  78:             Row() {
  79:               if (!this.isImport) {
  80:                 Button('复制')
  81:                   .width('45%')
  82:                   .height(44)
  83:                   .fontSize(16)
  84:                   .fontColor(this.colors.WHITE)
  85:                   .backgroundColor(this.colors.PRIMARY)
  86:                   .borderRadius(22)
  87:                   .onClick(() => {
  88:                     this.copyToClipboard(this.data.length > 0 ? this.data : this.message);
  89:                   })
  90: 
  91:                 Blank()
  92: 
  93:                 Button('关闭')
  94:                   .width('45%')
  95:                   .height(44)
  96:                   .fontSize(16)
  97:                   .fontColor(this.colors.WHITE)
  98:                   .backgroundColor(this.colors.GRAY_700)
  99:                   .borderRadius(22)
