 911:   async backupToCloudInBackground(): Promise<WebDavSyncResult> {
 912:     console.info('[WebDavSyncManager] ==== Starting cloud backup ====');
 913:     const backupStartMs = Date.now();
 914:     
 915:     const missing = this.requireConfigured();
 916:     if (missing !== null) {
 917:       console.error('[WebDavSyncManager] Backup failed: not configured');
 918:       return missing;
 919:     }
 920: 
 921:     // 检查是否已经在同步中
 922:     if (this.status === WebDavSyncStatus.SYNCING) {
 923:       console.warn('[WebDavSyncManager] Backup already in progress');
 924:       return WebDavSyncResult.fail('同步操作正在进行中', '请等待当前同步完成后再试');
 925:     }
 926: 
 927:     this.status = WebDavSyncStatus.SYNCING;
 928:     console.info('[WebDavSyncManager] Backup status set to SYNCING');
 929: 
 930:     // 先确保远程目录存在
 931:     const client = this.createClient();
 932:     const preflight = await this.preflightRemoteRoot(client);
 933:     if (preflight !== null) {
 934:       this.status = WebDavSyncStatus.ERROR;
 935:       console.error(`[WebDavSyncManager] Preflight check failed: ${preflight.message}`);
 936:       return preflight;
 937:     }
 938: 
 939:     // yield 给 UI 线程
 940:     await new Promise<void>((resolve) => setTimeout(resolve, 0));
 941: 
 942:     try {
 943:       const syncManager = DataSyncManager.getInstance();
 944: 
 945:       // 导出数据（在主线程执行，需要数据库）
 946:       console.info('[WebDavSyncManager] Exporting data from database');
 947:       const exportStartMs = Date.now();
 948:       const exportResult = await syncManager.exportData();
 949:       if (!exportResult.success) {
 950:         console.error(`[WebDavSyncManager] Export failed: ${exportResult.error}`);
 951:         return WebDavSyncResult.fail('备份失败', exportResult.error);
 952:       }
 953:       const exportMs = Date.now() - exportStartMs;
 954:       console.info(`[WebDavSyncManager] Export complete data_size=${exportResult.data.length} chars ms=${exportMs}`);
 955: 
 956:       // yield 给 UI 线程
 957:       await new Promise<void>((resolve) => setTimeout(resolve, 0));
 958: 
 959:       // 加密和上传数据（在 TaskPool 中执行，避免阻塞 UI）
 960:       console.info('[WebDavSyncManager] Starting encryption and upload in background');
 961:       const uploadStartMs = Date.now();
 962:       const params: BackupTaskWithEncryptParams = {
 963:         endpoint: this.settings.endpoint,
 964:         username: this.settings.username,
 965:         password: this.settings.password,
 966:         syncPassword: this.settings.syncPassword,
 967:         remoteRoot: this.settings.remoteRoot,
 968:         manifestJson: this.manifest.toJSON(),
 969:         backupFilePath: this.backupFilePath(),
 970:         plainData: exportResult.data
 971:       };
 972: 
 973:       const result = await this.executeTaskWithFallback<BackupTaskWithEncryptParams, BackupTaskResult>(executeBackupWithEncrypt, params);
 974:       const uploadMs = Date.now() - uploadStartMs;
 975: 
 976:       if (result.success) {
 977:         // 备份成功后，更新本地 VersionControl 时间戳，确保本地版本号与导出数据同步
 978:         try {
 979:           syncManager.getVersionControl().updateTimestamp();
 980:           console.info('[WebDavSyncManager] Local VersionControl timestamp updated after backup');
 981:         } catch (e) {
 982:           const errMsg = e instanceof Error ? e.message : String(e);
 983:           console.warn(`[WebDavSyncManager] Failed to update local VersionControl: ${errMsg}`);
 984:         }
 985:         
 986:         const totalBackupMs = Date.now() - backupStartMs;
 987:         console.info(`[WebDavSyncManager] ==== Backup completed successfully total_ms=${totalBackupMs} export_ms=${exportMs} upload_ms=${uploadMs} ====`);
 988:         return WebDavSyncResult.ok(result.message);
 989:       } else {
 990:         console.error(`[WebDavSyncManager] Backup failed: ${result.detail}`);
 991:         return WebDavSyncResult.fail('备份失败', result.detail);
 992:       }
 993:     } catch (e) {
 994:       const msg = e instanceof Error ? e.message : String(e);
 995:       const stack = e instanceof Error ? e.stack : '';
 996:       console.error(`[WebDavSyncManager] Backup failed with exception: ${msg}`);
 997:       if (stack) {
 998:         console.error(`[WebDavSyncManager] Stack trace: ${stack}`);
 999:       }
1000:       return WebDavSyncResult.fail('备份失败', msg);
1001:     } finally {
1002:       // 确保状态总是重置为 IDLE
1003:       this.status = WebDavSyncStatus.IDLE;
1004:       console.info('[WebDavSyncManager] Backup status reset to IDLE');
